import sys

def solve(n, arr, queries):
    arr = list(arr)
    def count_inv():
        c = 0
        for i in range(n):
            for j in range(i+1, n): c += arr[i] > arr[j]
        return c
    inv = count_inv(); out = []
    for q in queries:
        if q[0] == 1: arr[q[1]-1] = q[2]; inv = count_inv()
        else: out.append(str(inv))
    return "\n".join(out)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    arr = list(map(int, data[idx:idx+n])); idx += n
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        t = int(data[idx]); idx += 1
        if t == 1:
            i,x = int(data[idx]),int(data[idx+1]); idx += 2
            queries.append((t,i,x))
        else:
            queries.append((t,))
    print(solve(n, arr, queries))

